namespace localimage::vulkan { static std::string vr(VkResult r){return std::to_string((int)r);} VulkanBuffer::~VulkanBuffer(){destroy();} bool VulkanBuffer::findMemory(VkPhysicalDevice p,uint32_t bits,VkMemoryPropertyFlags f,uint32_t&o,std::string&e)const{VkPhysicalDeviceMemoryProperties m{};vkGetPhysicalDeviceMemoryProperties(p,&m);for(uint32_t i=0;i<m.memoryTypeCount;i++)if((bits&(1u<<i))&&(m.memoryTypes[i].propertyFlags&f)==f){o=i;return true;}e="No compatible memory type";return false;} bool VulkanBuffer::create(VkPhysicalDevice p,VkDevice d,VkDeviceSize s,VkBufferUsageFlags u,VkMemoryPropertyFlags f,uint32_t q,std::string&e){destroy();if(!s){e="zero buffer size";return false;}device_=d;size_=s;VkBufferCreateInfo bi{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};bi.size=s;bi.usage=u;bi.sharingMode=VK_SHARING_MODE_EXCLUSIVE;bi.queueFamilyIndexCount=1;bi.pQueueFamilyIndices=&q;VkResult r=vkCreateBuffer(d,&bi,nullptr,&buffer_);if(r!=VK_SUCCESS){e="vkCreateBuffer: "+vr(r);destroy();return false;}VkMemoryRequirements mr{};vkGetBufferMemoryRequirements(d,buffer_,&mr);uint32_t i;if(!findMemory(p,mr.memoryTypeBits,f,i,e)){destroy();return false;}VkMemoryAllocateInfo ai{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};ai.allocationSize=mr.size;ai.memoryTypeIndex=i;r=vkAllocateMemory(d,&ai,nullptr,&memory_);if(r!=VK_SUCCESS){e="vkAllocateMemory: "+vr(r);destroy();return false;}r=vkBindBufferMemory(d,buffer_,memory_,0);if(r!=VK_SUCCESS){e="vkBindBufferMemory: "+vr(r);destroy();return false;}return true;} bool VulkanBuffer::upload(const void*x,VkDeviceSize s,std::string&e){if(!memory_||s>size_){e="invalid upload";return false;}void*p=nullptr;VkResult r=vkMapMemory(device_,memory_,0,s,0,&p);if(r!=VK_SUCCESS){e="vkMapMemory upload: "+vr(r);return false;}std::memcpy(p,x,(size_t)s);vkUnmapMemory(device_,memory_);return true;} bool VulkanBuffer::download(void*x,VkDeviceSize s,std::string&e)const{if(!memory_||s>size_){e="invalid download";return false;}void*p=nullptr;VkResult r=vkMapMemory(device_,memory_,0,s,0,&p);if(r!=VK_SUCCESS){e="vkMapMemory download: "+vr(r);return false;}std::memcpy(x,p,(size_t)s);vkUnmapMemory(device_,memory_);return true;} void VulkanBuffer::destroy(){if(device_){if(buffer_)vkDestroyBuffer(device_,buffer_,nullptr);if(memory_)vkFreeMemory(device_,memory_,nullptr);}device_=VK_NULL_HANDLE;buffer_=VK_NULL_HANDLE;memory_=VK_NULL_HANDLE;size_=0;} }
